create table if not exists public.people_collections(id text primary key,title text not null,eyebrow text not null,description text not null,intro text not null,accent text not null check(accent in('gold','green','indigo')),created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.people_profiles(id uuid primary key default gen_random_uuid(),collection_id text not null references public.people_collections(id) on delete cascade,slug text not null,name text not null,lifespan text not null default '',origin text not null default '',role text not null default '',summary text not null default '',story jsonb not null default '[]',milestones jsonb not null default '[]',themes jsonb not null default '[]',sources jsonb not null default '[]',display_order int not null default 0,published boolean not null default true,created_at timestamptz default now(),updated_at timestamptz default now(),unique(collection_id,slug));
create index if not exists people_profiles_order_idx on public.people_profiles(collection_id,published,display_order);
alter table public.people_collections enable row level security; alter table public.people_profiles enable row level security;
drop policy if exists "Public read people collections" on public.people_collections; create policy "Public read people collections" on public.people_collections for select using(true);
drop policy if exists "Public read published people" on public.people_profiles; create policy "Public read published people" on public.people_profiles for select using(published=true);
grant select on public.people_collections,public.people_profiles to anon,authenticated;
insert into public.people_collections(id,title,eyebrow,description,intro,accent) values
('social-activists','Social Activists','People who organised for change','Explore the lives and work of people who challenged injustice and helped communities claim their rights.','Activism takes many forms: organising workers, defending the environment, expanding access to information and protecting children.','green'),
('freedom-fighters','Freedom Fighters','Lives from India''s freedom struggle','Discover the people, movements and difficult choices that shaped India''s long struggle against colonial rule.','The freedom movement was diverse and contested, involving constitutional politics, mass protest, revolutionary organising and regional struggles.','indigo') on conflict(id) do update set title=excluded.title,eyebrow=excluded.eyebrow,description=excluded.description,intro=excluded.intro,accent=excluded.accent,updated_at=now();